namespace CheckoutPricing.UnitTests;

public sealed class LoyaltyDiscountTests
{
    // Amounts are expressed in whole cents to avoid floating point rounding surprises.
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 4999, 4750)]
    [InlineData(LoyaltyTier.Bronze, 5000, 4700)]
    [InlineData(LoyaltyTier.Silver, 19999, 18400)]
